// WF-02 | Stage 2 - Caller Identification & Normalization
const item = $input.first().json;
const body = item.body || item.query || {};
const headers = item.headers || {};

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

const rawCorr = headers['x-correlation-id'] || body.correlation_id || '';
const correlationId = UUID_RE.test(rawCorr) ? rawCorr : uuid();

let fromPhone = String(body.From || body.from || body.phone || '').trim().replace(/[^\d+]/g, '');
if (/^0\d{9}$/.test(fromPhone)) fromPhone = '+84' + fromPhone.slice(1);

const callSid = body.CallSid || body.call_sid || ('CA' + Math.random().toString(16).slice(2, 18));
const speechText = String(body.SpeechResult || body.speech || body.message || body.input || 'Tôi muốn hỏi giá phần mềm AI Sales').trim();

return [{
  json: {
    call_sid: callSid,
    from_phone: fromPhone || '+84987654321',
    to_phone: body.To || '+842471099999',
    speech_text: speechText,
    correlation_id: correlationId,
    received_at: new Date().toISOString()
  }
}];

