// WF-02 | Stage 5 - Intent & Sentiment Engine
const caller = $('02 Caller Identification').first().json;
const lead = $('03 Lookup Caller Lead').first()?.json || {};
const runRecord = $('04 Create Workflow Run').first().json;

const text = caller.speech_text.toLowerCase();
let intent = 'general_faq';
let sentiment = 'neutral';
let isEscalation = false;

if (/gặp nhân viên|gặp tư vấn|nói chuyện với người|chuyển máy|hỗ trợ kỹ thuật|khiếu nại|lỗi/i.test(text)) {
  intent = 'speak_to_human';
  isEscalation = true;
  sentiment = /khiếu nại|bực mình|lỗi nặng/i.test(text) ? 'negative' : 'neutral';
} else if (/giá|bảng giá|chi phí|gói|bao nhiêu tiền|báo giá/i.test(text)) {
  intent = 'pricing';
  sentiment = 'positive';
} else if (/tính năng|voice ai|tổng đài|chức năng|giải pháp/i.test(text)) {
  intent = 'product_inquiry';
  sentiment = 'positive';
}

const callerName = (lead.first_name && lead.first_name !== 'Quý khách') ? `${lead.first_name} ${lead.last_name || ''}`.trim() : 'Quý khách';

return [{
  json: {
    workflow_run_id: runRecord.id,
    correlation_id: caller.correlation_id,
    call_sid: caller.call_sid,
    from_phone: caller.from_phone,
    lead_id: lead.id || null,
    caller_name: callerName,
    speech_text: caller.speech_text,
    intent,
    sentiment,
    is_escalation: isEscalation
  }
}];

// WF-02 | Stage 7a - Generate Transfer TwiML (Chuyển máy tư vấn viên)
const item = $input.first().json;
const hotline = '+842471088888';

const speechResponse = `Dạ em xin phép chuyển cuộc gọi của anh/chị ${item.caller_name} tới chuyên viên hỗ trợ ngay ạ. Xin vui lòng giữ máy.`;
const twiml = `
<Response>
  <Say voice="Polly.Aditi" language="vi-VN">${speechResponse}</Say>
  <Dial timeout="20">${hotline}</Dial>
</Response>
`.trim();

return [{
  json: {
    ...item,
    action_taken: 'transferred_to_human',
    speech_response: speechResponse,
    twiml
  }
}];

// WF-02 | Stage 7b - Generate Direct FAQ Voice Response (Lễ tân AI giải đáp)
const item = $input.first().json;

let answer = 'Dạ hệ thống AI Sales Agent bên em cung cấp giải pháp gọi tự động và quản lý khách hàng 360 độ.';
if (item.intent === 'pricing') {
  answer = 'Dạ gói Starter bên em có giá từ 2 triệu đồng/tháng, gói Pro đầy đủ Voice AI và CRM là 5 triệu đồng/tháng ạ.';
} else if (item.intent === 'product_inquiry') {
  answer = 'Dạ giải pháp AI Sales Agent tích hợp gọi điện đàm thoại tự động, chấm điểm khách hàng và tự đồng bộ CRM ạ.';
}

const fullSpeech = `Dạ em chào anh/chị ${item.caller_name}. ${answer} Em có thể hỗ trợ gửi chi tiết báo giá qua Zalo/Email cho mình được không ạ?`;
const twiml = `
<Response>
  <Say voice="Polly.Aditi" language="vi-VN">${fullSpeech}</Say>
  <Gather input="speech" timeout="5" language="vi-VN">
    <Say voice="Polly.Aditi" language="vi-VN">Anh chị cần hỗ trợ thêm thông tin gì nữa không ạ?</Say>
  </Gather>
</Response>
`.trim();

return [{
  json: {
    ...item,
    action_taken: 'resolved_by_ai',
    speech_response: fullSpeech,
    twiml
  }
}];

