// WF-02 | Stage 11 - Format Telephony Response
const caller = $('02 Caller Identification').first().json;
const intentData = $('05 Intent & Sentiment Engine').first().json;
const actionData = (intentData.is_escalation ? $('07a Generate Transfer TwiML') : $('07b Generate AI Voice Answer')).first().json;
const runRecord = $('04 Create Workflow Run').first().json;

return [{
  json: {
    status: 'success',
    data: {
      call_sid: caller.call_sid,
      caller: caller.from_phone,
      caller_name: intentData.caller_name,
      lead_id: intentData.lead_id,
      intent: intentData.intent,
      sentiment: intentData.sentiment,
      is_escalation: intentData.is_escalation,
      action_taken: actionData.action_taken,
      speech_response: actionData.speech_response,
      twiml: actionData.twiml,
      workflow_run_id: runRecord.id,
      correlation_id: caller.correlation_id
    }
  }
}];

// WF-02 | Stage 14 - Error Handle
const err = $input.first().json?.execution?.error || {};
const failedNode = $input.first().json?.execution?.lastNodeExecuted || 'unknown';

let workflowRunId = null;
try { workflowRunId = $('04 Create Workflow Run').first()?.json?.id || null; } catch (e) {}

return [{
  json: {
    workflowRunId,
    error: { message: err.message || 'Inbound call processing failed', failedNode, timestamp: new Date().toISOString() }
  }
}];
